/**
 * @method
 * @name bydfi#watchOrderBookForSymbols
 * @description watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://developers.bydfi.com/en/futures/websocket-market#limited-depth-information
 * @param {string[]} symbols unified array of symbols
 * @param {int} [limit] the maximum amount of order book entries to return (default and max is 100)
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Bydfi) WatchOrderBookForSymbolsAsync(symbols any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrderBookForSymbolsBody(ch, symbols, optionalArgs...)
	return ch
}
func (this *Bydfi) watchOrderBookForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols, nil, false)
	var depth string = "100"
	depthOption, paramsDepth := this.HandleOptionStringAndParams(params, "watchOrderBookForSymbols", "depth", depth)
	var frequency string = "100ms"
	frequencyOption, paramsFrequency := this.HandleOptionStringAndParams(paramsDepth, "watchOrderBookForSymbols", "frequency", frequency)
	var channelSuffix string = ""
	if frequencyOption != nil && *frequencyOption == "100ms" {
		channelSuffix = "@100ms"
	}
	var channels []any = []any{}
	var messageHashes []any = []any{}
	for i := 0; i < len(symbolsNormalized); i++ {
		var symbol string = symbolsNormalized[i]
		var market map[string]any = this.Market(symbol)
		channels = append(channels, ccxt.Add(ccxt.Add(ccxt.Add(market["id"], "@depth"), depthOption), channelSuffix))
		messageHashes = append(messageHashes, "orderbook::"+symbol)
	}

	var orderbook ccxt.OrderBookInterface = ccxt.PanicOnError((<-this.WatchPublicAsync(messageHashes, channels, paramsFrequency))).(ccxt.OrderBookInterface)

	ch <- orderbook.(ccxt.OrderBookInterface).Limit()
	return nil
}

/**
 * @method
 * @name bydfi#unWatchOrderBookForSymbols
 * @description unWatches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://developers.bydfi.com/en/futures/websocket-market#limited-depth-information
 * @param {string[]} symbols unified array of symbols
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.method] either '/market/level2' or '/spotMarket/level2Depth5' or '/spotMarket/level2Depth50' default is '/market/level2'
 * @returns {object} A dictionary of [order book structures]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Bydfi) UnWatchOrderBookForSymbolsAsync(symbols any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.unWatchOrderBookForSymbolsBody(ch, symbols, optionalArgs...)
	return ch
}
func (this *Bydfi) unWatchOrderBookForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols, nil, false)
	var depth string = "100"
	depthOption, paramsDepth := this.HandleOptionStringAndParams(params, "watchOrderBookForSymbols", "depth", depth)
	var frequency string = "100ms"
	frequencyOption, paramsFrequency := this.HandleOptionStringAndParams(paramsDepth, "watchOrderBookForSymbols", "frequency", frequency)
	var channelSuffix string = ""
	if frequencyOption != nil && *frequencyOption == "100ms" {
		channelSuffix = "@100ms"
	}
	var channels []any = []any{}
	var messageHashes []any = []any{}
	for i := 0; i < len(symbolsNormalized); i++ {
		var symbol string = symbolsNormalized[i]
		var market map[string]any = this.Market(symbol)
		channels = append(channels, ccxt.Add(ccxt.Add(ccxt.Add(market["id"], "@depth"), depthOption), channelSuffix))
		messageHashes = append(messageHashes, "unsubscribe::orderbook::"+symbol)
	}
	var subscription map[string]any = map[string]any{
		"topic":   "orderbook",
		"symbols": symbolsNormalized,
	}
	var paramsExtended map[string]any = this.Extend(paramsFrequency, map[string]any{
		"unsubscribe": true,
	})

	ch <- ccxt.PanicOnError((<-this.WatchPublicAsync(messageHashes, channels, paramsExtended, subscription)))
	return nil
}
func (this *Bydfi) HandleOrderBook(client any, message any) {
	//
	//     {
	//         "a": [ [ 150000, 15 ], ... ],
	//         "b": [ [ 90450.7, 3615 ], ... ],
	//         "s": "BTC-USDT",
	//         "e": "depthUpdate",
	//         "E": 1766577624512
	//     }
	//
	var marketId *string = this.SafeString(message, "s")
	var symbol *string = this.SafeSymbol(marketId)
	var timestamp *int64 = this.SafeInteger(message, "E")
	if !(ccxt.InOp(this.Orderbooks, symbol)) {
		ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook())
	}
	var orderbook any = ccxt.GetValue(this.Orderbooks, symbol)
	var parsed map[string]any = this.ParseOrderBook(message, symbol, timestamp, "b", "a")
	orderbook.(ccxt.OrderBookInterface).Reset(parsed)
	var messageHash string = "orderbook::" + *symbol
	ccxt.AddElementToObject(this.Orderbooks, symbol, orderbook)
	client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
}

