func (this *Bydfi) watchOrdersForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols, nil, true)
	var messageHashes []any = []any{}
	if ccxt.IsEqual(symbolsNormalized, nil) {
		messageHashes = append(messageHashes, "orders")
	} else {
		for i := 0; i < len(symbolsNormalized); i++ {
			var symbol string = symbolsNormalized[i]
			messageHashes = append(messageHashes, "orders::"+symbol)
		}
	}

	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.WatchPrivateAsync(messageHashes, params))))
	var first map[string]any = ccxt.SafeMapTyped(orders, 0)
	var tradeSymbol *string = this.SafeString(first, "symbol")
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(orders).GetLimit(tradeSymbol, limit)
	}

	ch <- this.FilterBySinceLimit(orders, since, limitResolved, "timestamp", true)
	return nil
}
func (this *Bydfi) HandleOrder(client any, message any) {
	//
	//     {
	//         "T": 1766588450558,
	//         "E": 1766588450685,
	//         "e": "ORDER_TRADE_UPDATE",
	//         "o": {
	//             "S": "BUY",
	//             "ap": "0",
	//             "cpt": false,
	//             "ct": "future",
	//             "ev": "0",
	//             "fee": "0",
	//             "lv": 2,
	//             "mt": "isolated",
	//             "o": "7409609004526010368",
	//             "p": "1000",
	//             "ps": "BOTH",
	//             "pt": "ONE_WAY",
	//             "ro": false,
	//             "s": "ETH-USDC",
	//             "st": "NEW",
	//             "t": "LIMIT",
	//             "tp": "0",
	//             "u": "0.001",
	//             "v": "2"
	//         }
	//     }
	//
	var rawOrder map[string]any = ccxt.MapTyped(this.SafeDict(message, "o", map[string]any{}))
	var marketId *string = this.SafeString(rawOrder, "s")
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "orders"
	var symbolMessageHash string = messageHash + "::" + *symbol
	if ccxt.IsEqual(this.Orders, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var orders any = this.Orders
	var order map[string]any = ccxt.MapTyped(this.ParseWsOrder(rawOrder, market))
	var lastUpdateTimestamp *int64 = this.SafeInteger(message, "T")
	order["lastUpdateTimestamp"] = lastUpdateTimestamp
	orders.(ccxt.Appender).Append(order)
	client.(ccxt.ClientInterface).Resolve(orders, messageHash)
	client.(ccxt.ClientInterface).Resolve(orders, symbolMessageHash)
}
func (this *Bydfi) ParseWsOrder(order any, optionalArgs ...any) any {
	//
	//     {
	//         "S": "BUY",
	//         "ap": "0",
	//         "cpt": false,
	//         "ct": "future",
	//         "ev": "0",
	//         "fee": "0",
	//         "lv": 2,
	//         "mt": "isolated",
	//         "o": "7409609004526010368",
	//         "p": "1000",
	//         "ps": "BOTH",
	//         "pt": "ONE_WAY",
	//         "ro": false,
	//         "s": "ETH-USDC",
	//         "st": "NEW",
	//         "t": "LIMIT",
	//         "tp": "0",
	//         "u": "0.001",
	//         "v": "2"
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(order, "s")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var rawStatus *string = this.SafeString(order, "st")
	var rawType *string = this.SafeString(order, "t")
	var fee map[string]any = nil
	var feeCost *string = this.SafeString(order, "fee")
	if feeCost != nil {
		fee = map[string]any{
			"cost":     ccxt.Precise.StringAbs(feeCost),
			"currency": marketResolved["quote"],
		}
	}
	return this.SafeOrder(map[string]any{
		"info":                order,
		"id":                  this.SafeString(order, "o"),
		"clientOrderId":       this.SafeString(order, "cid"),
		"timestamp":           nil,
		"datetime":            nil,
		"lastTradeTimestamp":  nil,
		"lastUpdateTimestamp": nil,
		"status":              this.ParseOrderStatus(rawStatus),
		"symbol":              marketResolved["symbol"],
		"type":                this.ParseOrderType(rawType),
		"timeInForce":         nil,
		"postOnly":            nil,
		"reduceOnly":          this.SafeBool(order, "ro"),
		"side":                this.SafeStringLower(order, "S"),
		"price":               this.SafeString(order, "p"),
		"triggerPrice":        nil,
		"stopLossPrice":       nil,
		"takeProfitPrice":     nil,
		"amount":              this.SafeString(order, "v"),
		"filled":              this.SafeString(order, "ev"),
		"remaining":           this.SafeString(order, "qty"),
		"cost":                nil,
		"trades":              nil,
		"fee":                 fee,
		"average":             this.OmitZero(this.SafeString(order, "ap")),
	}, marketResolved)
}

/**
 * @method
 * @name bydfi#watchPositions
 * @description watch all open positions
 * @see https://developers.bydfi.com/en/futures/websocket-account#balance-and-position-update-push
 * @param {string[]} [symbols] list of unified market symbols
 * @param {int} [since] the earliest time in ms to fetch positions for
 * @param {int} [limit] the maximum number of positions to retrieve
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
 */
func (this *Bydfi) WatchPositionsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Bydfi) watchPositionsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbols []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols, nil, true)
	var messageHashes []any = []any{}
	var messageHash string = "positions"
	if ccxt.IsEqual(symbolsNormalized, nil) {
		messageHashes = append(messageHashes, messageHash)
	} else {
		for i := 0; i < len(symbolsNormalized); i++ {
			var symbol string = symbolsNormalized[i]
			messageHashes = append(messageHashes, messageHash+"::"+symbol)
		}
	}

	positions := (<-this.WatchPrivateAsync(messageHashes, params))
	ccxt.PanicOnError(positions)
	if this.NewUpdates {

		ch <- positions
		return nil
	}

	ch <- this.FilterBySymbolsSinceLimit(this.Positions, symbolsNormalized, since, limit, true)
	return nil
}
func (this *Bydfi) HandlePositions(client any, message any) {
	//
	//     {
	//         "a": {
	//             "B": [
	//                 {
	//                     "a": "USDC",
	//                     "ba": "0",
	//                     "im": "1.46282986",
	//                     "om": "0",
	//                     "tfm": "1.46282986",
	//                     "wb": "109.86879703"
	//                 }
	//             ],
	//             "m": "ORDER",
	//             "p": [
	//                 {
	//                     "S": "1",
	//                     "ap": "2925.81666667",
	//                     "c": "USDC",
	//                     "ct": "FUTURE",
	//                     "l": 2,
	//                     "lq": "1471.1840621072728637",
	//                     "lv": "0",
	//                     "ma": "0",
	//                     "mt": "ISOLATED",
	//                     "pm": "1.4628298566666665",
	//                     "pt": "ONEWAY",
	//                     "rp": "-0.00036721",
	//                     "s": "ETH-USDC",
	//                     "t": "0",
	//                     "uq": "0.001",
	//                     "v": "1"
	//                 }
	//             ]
	//         },
	//         "T": 1766592694451,
	//         "E": 1766592694554,
	//         "e": "ACCOUNT_UPDATE"
	//     }
	//
	var data map[string]any = ccxt.SafeMapTyped(message, "a")
	var positionsData []any = ccxt.SafeListTyped(data, "p")
	var rawPosition map[string]any = ccxt.MapTyped(this.SafeDict(positionsData, 0, map[string]any{}))
	var marketId *string = this.SafeString(rawPosition, "s")
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "positions"
	var symbolMessageHash string = messageHash + "::" + *symbol
	if ccxt.IsEqual(this.Positions, nil) {
		this.Positions = ccxt.NewArrayCacheBySymbolBySide()
	}
	var cache any = this.Positions
	var parsedPosition any = this.ParseWsPosition(rawPosition, market)
	var timestamp *int64 = this.SafeInteger(message, "T")
	ccxt.AddElementToObject(parsedPosition, "timestamp", timestamp)
	ccxt.AddElementToObject(parsedPosition, "datetime", this.Iso8601(timestamp))
	cache.(ccxt.Appender).Append(parsedPosition)
	client.(ccxt.ClientInterface).Resolve([]any{parsedPosition}, messageHash)
	client.(ccxt.ClientInterface).Resolve([]any{parsedPosition}, symbolMessageHash)
}
func (this *Bydfi) ParseWsPosition(position map[string]any, optionalArgs ...any) any {
	//
	//     {
	//         "S": "1",
	//         "ap": "2925.81666667",
	//         "c": "USDC",
	//         "ct": "FUTURE",
	//         "l": 2,
	//         "lq": "1471.1840621072728637",
	//         "lv": "0",
	//         "ma": "0",
	//         "mt": "ISOLATED",
	//         "pm": "1.4628298566666665",
	//         "pt": "ONEWAY",
	//         "rp": "-0.00036721",
	//         "s": "ETH-USDC",
	//         "t": "0",
	//         "uq": "0.001",
	//         "v": "1"
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "s")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var rawPositionSide *string = this.SafeString(position, "S")
	var positionMode *string = this.SafeString(position, "pt")
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          this.SafeString(position, "id"),
		"symbol":                      marketResolved["symbol"],
		"entryPrice":                  this.ParseNumber(this.SafeString(position, "ap")),
		"markPrice":                   nil,
		"lastPrice":                   nil,
		"notional":                    nil,
		"collateral":                  nil,
		"unrealizedPnl":               nil,
		"realizedPnl":                 this.ParseNumber(this.SafeString(position, "rp")),
		"side":                        this.ParseWsPositionSide(rawPositionSide),
		"contracts":                   this.ParseNumber(this.SafeString(position, "v")),
		"contractSize":                this.ParseNumber(this.SafeString(position, "uq")),
		"timestamp":                   nil,
		"datetime":                    nil,
		"lastUpdateTimestamp":         nil,
		"hedged":                      (positionMode == nil || *positionMode != "ONEWAY"),
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": nil,
		"initialMargin":               this.ParseNumber(this.SafeString(position, "pm")),
		"initialMarginPercentage":     nil,
		"leverage":                    this.SafeInteger(position, "l"),
		"liquidationPrice":            this.ParseNumber(this.SafeString(position, "lq")),
		"marginRatio":                 nil,
		"marginMode":                  this.SafeStringLower(position, "mt"),
		"percentage":                  nil,
	})
}
func (this *Bydfi) ParseWsPositionSide(rawPositionSide *string) *string {
	var sides map[string]any = map[string]any{
		"1": "long",
		"2": "short",
	}
	return this.SafeString(sides, rawPositionSide, rawPositionSide)
}

/**
 * @method
 * @name bydfi#watchBalance
 * @description watch balance and get the amount of funds available for trading or funds locked in orders
 * @see https://developers.bydfi.com/en/futures/websocket-account#balance-and-position-update-push
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Bydfi) WatchBalanceAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Bydfi) watchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"))
	var client ccxt.ClientInterface = this.Client(url)
	this.FetchBalanceSnapshot(client)
	var options map[string]any = ccxt.SafeMapTyped(this.Options, "watchBalance")
	var fetchBalanceSnapshot *bool = this.SafeBool(options, "fetchBalanceSnapshot", false)
	var awaitBalanceSnapshot *bool = this.SafeBool(options, "awaitBalanceSnapshot", true)
	if (fetchBalanceSnapshot != nil && *fetchBalanceSnapshot == true) && (awaitBalanceSnapshot != nil && *awaitBalanceSnapshot == true) {

		ccxt.PanicOnError((<-client.(ccxt.ClientInterface).Future("fetchBalanceSnapshot")))
	}
	var messageHash string = "balance"

	ch <- ccxt.PanicOnError((<-this.WatchPrivateAsync([]any{messageHash}, params)))
	return nil
}
func (this *Bydfi) FetchBalanceSnapshot(client any) {
	var options map[string]any = ccxt.SafeMapTyped(this.Options, "watchBalance")
	var fetchBalanceSnapshot *bool = this.SafeBool(options, "fetchBalanceSnapshot", false)
	if fetchBalanceSnapshot != nil && *fetchBalanceSnapshot == true {
		var messageHash string = "fetchBalanceSnapshot"
		if !(ccxt.InOp(client.(ccxt.ClientInterface).GetFutures(), messageHash)) {
			client.(ccxt.ClientInterface).Future(messageHash)
			this.Spawn(this.LoadBalanceSnapshotAsync, client, messageHash)
		}
	}
}
func (this *Bydfi) LoadBalanceSnapshotAsync(client any, messageHash any) <-chan any {
	ch := make(chan any, 1)
	go this.loadBalanceSnapshotBody(ch, client, messageHash)
	return ch
}
func (this *Bydfi) loadBalanceSnapshotBody(ch chan any, client any, messageHash any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = map[string]any{
		"type": "swap",
	}

	response := (<-this.FetchBalanceAsync(params))
	ccxt.PanicOnError(response)
	this.Balance = this.Extend(response, this.Balance)
	// don't remove the future from the .futures cache
	var future any = ccxt.GetValue(client.(ccxt.ClientInterface).GetFutures(), messageHash)
	future.(*ccxt.Future).Resolve()
	client.(ccxt.ClientInterface).Resolve(this.Balance, "balance")
	return nil
}
func (this *Bydfi) HandleBalance(client any, message any) {
	//
	//     {
	//         "a": {
	//             "B": [
	//                 {
	//                     "a": "USDC",
	//                     "ba": "0",
	//                     "im": "1.46282986",
	//                     "om": "0",
	//                     "tfm": "1.46282986",
	//                     "wb": "109.86879703"
	//                 }
	//             ],
	//             "m": "ORDER",
	//             "p": [
	//                 {
	//                     "S": "1",
	//                     "ap": "2925.81666667",
	//                     "c": "USDC",
	//                     "ct": "FUTURE",
	//                     "l": 2,
	//                     "lq": "1471.1840621072728637",
	//                     "lv": "0",
	//                     "ma": "0",
	//                     "mt": "ISOLATED",
	//                     "pm": "1.4628298566666665",
	//                     "pt": "ONEWAY",
	//                     "rp": "-0.00036721",
	//                     "s": "ETH-USDC",
	//                     "t": "0",
	//                     "uq": "0.001",
	//                     "v": "1"
	//                 }
	//             ]
	//         },
	//         "T": 1766592694451,
	//         "E": 1766592694554,
	//         "e": "ACCOUNT_UPDATE"
	//     }
	//
	var messageHash string = "balance"
	if ccxt.InOp(client.(ccxt.ClientInterface).GetFutures(), messageHash) {
		var data map[string]any = ccxt.SafeMapTyped(message, "a")
		var balances []any = ccxt.SafeListTyped(data, "B")
		var timestamp *int64 = this.SafeInteger(message, "T")
		var result map[string]any = map[string]any{
			"info":      message,
			"timestamp": timestamp,
			"datetime":  this.Iso8601(timestamp),
		}
		for i := 0; i < len(balances); i++ {
			var balance map[string]any = ccxt.SafeMapTyped(balances, i)
			var currencyId *string = this.SafeString(balance, "a")
			var code *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["total"] = this.SafeString(balance, "wb")
			account["used"] = this.SafeString(balance, "tfm")
			if code != nil {
				result[*code] = account
			}
		}
		var parsedBalance any = this.SafeBalance(result)
		this.Balance = this.Extend(this.Balance, parsedBalance)
		client.(ccxt.ClientInterface).Resolve(this.Balance, messageHash)
	}
}
func (this *Bydfi) HandleSubscriptionStatus(client any, message any) any {
	//
	//     {
	//         "result": true,
	//         "id": 1
	//     }
	//
	var id *string = this.SafeString(message, "id")
	var subscriptionsById map[string]any = this.IndexBy(client.(ccxt.ClientInterface).GetSubscriptions(), "id")
	var subscription any = this.SafeDict(subscriptionsById, id, map[string]any{})
	var isUnSubMessage *bool = this.SafeBool(subscription, "unsubscribe", false)
	if isUnSubMessage != nil && *isUnSubMessage == true {
		this.HandleUnSubscription(client, subscription)
	}
	return message
}
func (this *Bydfi) HandleUnSubscription(client any, subscription any) {
	var messageHashes []any = ccxt.SafeListTyped(subscription, "messageHashes")
	var subHashIsPrefix *bool = this.SafeBool(subscription, "subHashIsPrefix", false)
	for i := 0; i < len(messageHashes); i++ {
		var unsubHash any = func() any {
			if i >= 0 && i < len(messageHashes) {
				return ccxt.DerefScalar(messageHashes[i])
			}
			return nil
		}()
		var subHash string = ccxt.Replace(unsubHash, "unsubscribe::", "")
		this.CleanUnsubscription(ccxt.AsClient(client), subHash, unsubHash, subHashIsPrefix)
	}
	this.CleanCache(subscription)
}
func (this *Bydfi) HandlePong(client any, message any) any {
	//
	//     {
	//         "id": 1,
	//         "result": "pong"
	//     }
	//
	client.(ccxt.ClientInterface).SetLastPong(this.Milliseconds())
	return message
}
func (this *Bydfi) HandleErrorMessage(client any, message any) {
	//
	//     {
	//         "msg": "Service error",
	//         "code": "-1"
	//     }
	//
	var code *string = this.SafeString(message, "code")
	var msg *string = this.SafeString(message, "msg")
	var feedback string = this.Id + " " + this.Json(message)
	this.ThrowExactlyMatchedException(this.Exceptions["exact"], msg, feedback)
	this.ThrowBroadlyMatchedException(this.Exceptions["broad"], msg, feedback)
	this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
	panic(ccxt.ExchangeError(feedback))
}
func (this *Bydfi) HandleMessage(client any, message any) {
	var code *string = this.SafeString(message, "code")
	if (code != nil) && (code == nil || *code != "0") {
		this.HandleErrorMessage(client, message)
	}
	var result *string = this.SafeString(message, "result")
	if result != nil && *result == "pong" {
		this.HandlePong(client, message)
	} else if result != nil {
		this.HandleSubscriptionStatus(client, message)
	} else {
		var event *string = this.SafeString(message, "e")
		if event != nil && *event == "24hrTicker" {
			this.HandleTicker(client, message)
		} else if event != nil && *event == "kline" {
			this.HandleOHLCV(client, message)
		} else if event != nil && *event == "depthUpdate" {
			this.HandleOrderBook(client, message)
		} else if event != nil && *event == "ORDER_TRADE_UPDATE" {
			this.HandleOrder(client, message)
		} else if event != nil && *event == "ACCOUNT_UPDATE" {
			var account map[string]any = ccxt.SafeMapTyped(message, "a")
			var balances []any = ccxt.SafeListTyped(account, "B")
			var balancesLength int = len(balances)
			if balancesLength > 0 {
				this.HandleBalance(client, message)
			}
			var positions []any = ccxt.SafeListTyped(account, "p")
			var positionsLength int = len(positions)
			if positionsLength > 0 {
				this.HandlePositions(client, message)
			}
		}
	}
}

func NewBydfi(userConfig map[string]any) *Bydfi {
	p := newBydfi()
	p.Init(userConfig)
	return p
}

func (this *Bydfi) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

